class Solution {
public:
    int countPairs(vector<int>& nums) {
        auto check = [](int x, int y) {
            string sx = to_string(x);
            string sy = to_string(y);
            int max_len = max(sx.size(), sy.size());
            while (sx.size() < max_len) sx = "0" + sx;
            while (sy.size() < max_len) sy = "0" + sy;
            vector<int> diffs;
            for (int i = 0; i < max_len; ++i) {
                if (sx[i] != sy[i]) diffs.push_back(i);
            }
            if (diffs.empty()) return true;
            if (diffs.size() == 2) {
                int i = diffs[0], j = diffs[1];
                return sx[i] == sy[j] && sx[j] == sy[i];
            }
            return false;
        };
        int ans = 0;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (check(nums[i], nums[j])) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int countPairs(int[] nums) {
        int ans = 0;
        int n = nums.length;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (check(nums[i], nums[j])) ans++;
            }
        }
        return ans;
    }

    private boolean check(int x, int y) {
        String sx = Integer.toString(x);
        String sy = Integer.toString(y);
        int maxLen = Math.max(sx.length(), sy.length());
        while (sx.length() < maxLen) sx = "0" + sx;
        while (sy.length() < maxLen) sy = "0" + sy;
        List<Integer> diffs = new ArrayList<>();
        for (int i = 0; i < maxLen; ++i) {
            if (sx.charAt(i) != sy.charAt(i)) diffs.add(i);
        }
        if (diffs.isEmpty()) return true;
        if (diffs.size() == 2) {
            int i = diffs.get(0), j = diffs.get(1);
            return sx.charAt(i) == sy.charAt(j) && sx.charAt(j) == sy.charAt(i);
        }
        return false;
    }
}

var countPairs = function(nums) {
    const check = (x, y) => {
        let sx = String(x);
        let sy = String(y);
        const maxLen = Math.max(sx.length, sy.length);
        sx = sx.padStart(maxLen, '0');
        sy = sy.padStart(maxLen, '0');
        const diffs = [];
        for (let i = 0; i < maxLen; i++) {
            if (sx[i] !== sy[i]) diffs.push(i);
        }
        if (diffs.length === 0) return true;
        if (diffs.length === 2) {
            const [i, j] = diffs;
            return sx[i] === sy[j] && sx[j] === sy[i];
        }
        return false;
    };
    let ans = 0;
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (check(nums[i], nums[j])) ans++;
        }
    }
    return ans;
};
